CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DocumentoIdentidad" character varying(20) NOT NULL,
    "NombreCompleto" character varying(150) NOT NULL,
    "Telefono" character varying(20),
    "Email" character varying(150),
    CONSTRAINT "PK__Clientes__3214EC070C5DA8E9" PRIMARY KEY ("Id")
);

CREATE TABLE "Especialidades" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" character varying(100) NOT NULL,
    "CostoBase" numeric(10,2) NOT NULL,
    CONSTRAINT "PK__Especial__3214EC0723BFF743" PRIMARY KEY ("Id")
);

CREATE TABLE "Insumos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "NombreProducto" character varying(150) NOT NULL,
    "Tipo" character varying(50) NOT NULL,
    "StockActual" integer NOT NULL,
    "PrecioUnitario" numeric(10,2) NOT NULL,
    CONSTRAINT "PK__Insumos__3214EC0728749262" PRIMARY KEY ("Id")
);

CREATE TABLE "Roles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" character varying(100) NOT NULL,
    "PermisosEscritura" boolean NOT NULL,
    CONSTRAINT "PK__Roles__3214EC07445D2FB3" PRIMARY KEY ("Id")
);

CREATE TABLE "Facturas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClienteId" integer NOT NULL,
    "FechaEmision" date NOT NULL DEFAULT (CURRENT_DATE),
    "MontoImpuestos" numeric(10,2) NOT NULL,
    "MontoTotal" numeric(10,2) NOT NULL,
    CONSTRAINT "PK__Facturas__3214EC07EDC3F268" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Facturas_Clientes" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id")
);

CREATE TABLE "Pacientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClienteId" integer NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Especie" character varying(50) NOT NULL,
    "Raza" character varying(50),
    "Peso" numeric(5,2),
    "Alergias" text,
    CONSTRAINT "PK__Paciente__3214EC076582479F" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Pacientes_Clientes" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id")
);

CREATE TABLE "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RolId" integer NOT NULL,
    "NombreCompleto" character varying(150) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "PasswordHash" character varying(256) NOT NULL,
    CONSTRAINT "PK__Usuarios__3214EC0795B09A7E" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Usuarios_Roles" FOREIGN KEY ("RolId") REFERENCES "Roles" ("Id")
);

CREATE TABLE public."Auditoria" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "FechaHora" timestamp with time zone NOT NULL,
    "UsuarioId" integer,
    "UsuarioNombre" text,
    "Accion" text NOT NULL,
    "Entidad" text NOT NULL,
    "RegistroId" integer NOT NULL,
    "ValoresAnteriores" jsonb,
    "ValoresNuevos" jsonb,
    "Origen" text NOT NULL,
    "OperacionId" uuid NOT NULL,
    CONSTRAINT "PK_Auditoria" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Auditoria_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE SET NULL
);

CREATE TABLE "Citas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PacienteId" integer NOT NULL,
    "UsuarioId" integer NOT NULL,
    "EspecialidadId" integer NOT NULL,
    "FechaHora" timestamp without time zone NOT NULL,
    "Estado" character varying(50) NOT NULL,
    CONSTRAINT "PK__Citas__3214EC07A639186A" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Citas_Especialidades" FOREIGN KEY ("EspecialidadId") REFERENCES "Especialidades" ("Id"),
    CONSTRAINT "FK_Citas_Pacientes" FOREIGN KEY ("PacienteId") REFERENCES "Pacientes" ("Id"),
    CONSTRAINT "FK_Citas_Usuarios" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id")
);

CREATE TABLE public."ReconocimientoFacial" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer NOT NULL,
    "DescriptorFacial" jsonb NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT (now()),
    "FechaActualizacion" timestamp with time zone,
    "UltimoAcceso" timestamp with time zone,
    "Activo" boolean NOT NULL DEFAULT TRUE,
    "ConsentimientoFecha" timestamp with time zone,
    "ConsentimientoAdministradorId" integer,
    "ConsentimientoVersion" text,
    CONSTRAINT "PK_ReconocimientoFacial" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ReconocimientoFacial_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Consultas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PacienteId" integer NOT NULL,
    "CitaId" integer,
    "Motivo" text NOT NULL,
    "Diagnostico" text,
    CONSTRAINT "PK__Consulta__3214EC07AF440D4C" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Consultas_Citas" FOREIGN KEY ("CitaId") REFERENCES "Citas" ("Id"),
    CONSTRAINT "FK_Consultas_Pacientes" FOREIGN KEY ("PacienteId") REFERENCES "Pacientes" ("Id")
);

CREATE TABLE "DetallesFactura" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FacturaId" integer NOT NULL,
    "ConsultaId" integer,
    "InsumoId" integer,
    "Subtotal" numeric(10,2) NOT NULL,
    CONSTRAINT "PK__Detalles__3214EC073EE87D18" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DetallesFactura_Consultas" FOREIGN KEY ("ConsultaId") REFERENCES "Consultas" ("Id"),
    CONSTRAINT "FK_DetallesFactura_Facturas" FOREIGN KEY ("FacturaId") REFERENCES "Facturas" ("Id"),
    CONSTRAINT "FK_DetallesFactura_Insumos" FOREIGN KEY ("InsumoId") REFERENCES "Insumos" ("Id")
);

CREATE TABLE "Recetas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ConsultaId" integer NOT NULL,
    "FechaEmision" date NOT NULL,
    "ValidaHasta" date NOT NULL,
    CONSTRAINT "PK__Recetas__3214EC07247EC520" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Recetas_Consultas" FOREIGN KEY ("ConsultaId") REFERENCES "Consultas" ("Id")
);

CREATE TABLE "DetallesReceta" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RecetaId" integer NOT NULL,
    "InsumoId" integer NOT NULL,
    "Dosis" character varying(100) NOT NULL,
    "DuracionDias" integer NOT NULL,
    CONSTRAINT "PK__Detalles__3214EC074095EE85" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DetallesReceta_Insumos" FOREIGN KEY ("InsumoId") REFERENCES "Insumos" ("Id"),
    CONSTRAINT "FK_DetallesReceta_Recetas" FOREIGN KEY ("RecetaId") REFERENCES "Recetas" ("Id")
);

